def ref(code, author, year, title, url, use, appraisal, licence, short, limit, **extra):
    return dict(id=code, author=author, year=year, title=title, url=url,
        kind='practice_guidance' if code.startswith('S') else 'peer_reviewed_research',
        use=use, appraisal=appraisal, licence=licence, checked_on=CHECKED_ON,
        slide_title=short, slide_limit=limit, **extra)


